def _json_file(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(value, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def responses(*items):
    queue = iter(items)
    return lambda _messages: next(queue)


def _make_package(
    tmp_path,
    *,
    manifest_updates=None,
    workspace_files=None,
    checks=None,
):
    root = tmp_path / "package"
    manifest = {
        "schema_version": 1,
        "id": "test-package",
        "prompt": "Update value.txt.",
        "max_steps": 4,
        "editable_paths": ["value.txt"],
    }
    manifest.update(manifest_updates or {})
    _json_file(root / "task.json", manifest)
    for relative, contents in (workspace_files or {"value.txt": "old\n"}).items():
        target = root / "workspace" / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(contents, encoding="utf-8")
    _json_file(
        root / "held_out_tests" / "checks.json",
        checks
        or {
            "schema_version": 1,
            "checks": [
                {
                    "type": "text_equals",
                    "name": "value-updated",
                    "path": "value.txt",
                    "expected": "new\n",
                }
            ],
        },
    )
    return root


def _package_bytes(root):
    return {
        path.relative_to(root).as_posix(): path.read_bytes()
        for path in root.rglob("*")
        if path.is_file()
    }


def _tree_state(root):
    entries = tuple(
        sorted(
            (
                path.relative_to(root).as_posix(),
                "directory" if path.is_dir() else "file",
                stat.S_IMODE(path.lstat().st_mode),
            )
            for path in root.rglob("*")
        )
    )
    return entries, _package_bytes(root)


def _stage_package(root, tmp_path, name="candidate"):
    return TaskPackage.load(root).stage(tmp_path / name)


def _freeze_and_grade(staged, tmp_path, name="frozen"):
    candidate = staged.freeze(tmp_path / name)
    return candidate, StaticHeldOutGrader().grade(staged, candidate)


def test_shipped_task_packages_are_sealed_inert_trees():
    assert {path.name for path in EVAL_ROOT.iterdir()} == set(PACKAGE_FILES)

    for task_id, expected_files in PACKAGE_FILES.items():
        root = EVAL_ROOT / task_id
        actual_files = {
            path.relative_to(root).as_posix()
            for path in root.rglob("*")
            if path.is_file()
        }
        assert actual_files == expected_files
        assert not any(path.is_symlink() for path in root.rglob("*"))
        assert not any(
            path.stat().st_mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
            for path in root.rglob("*")
            if path.is_file()
        )
        manifest = json.loads((root / "task.json").read_text(encoding="utf-8"))
        checks = json.loads(
            (root / "held_out_tests" / "checks.json").read_text(encoding="utf-8")
        )
        assert manifest["schema_version"] == 1
        assert manifest["id"] == task_id
        assert set(manifest) == {
            "schema_version",
            "id",
            "prompt",
            "max_steps",
            "editable_paths",
        }
        assert set(checks) == {"schema_version", "checks"}
        assert checks["schema_version"] == 1


