def test_staging_records_a_stable_sorted_snapshot_and_tree_hash(tmp_path):
    root = _make_package(
        tmp_path,
        workspace_files={
            "z-last.txt": "last\n",
            "nested/a-first.txt": "first\n",
        },
        manifest_updates={
            "editable_paths": ["nested/a-first.txt", "z-last.txt"],
        },
    )
    package = TaskPackage.load(root)
    first = package.stage(tmp_path / "first")
    second = package.stage(tmp_path / "second")

    assert [snapshot.path for snapshot in first.initial_files] == [
        "nested/a-first.txt",
        "z-last.txt",
    ]
    assert first.initial_files == second.initial_files
    assert first.initial_tree_sha256 == second.initial_tree_sha256
    assert len(first.initial_tree_sha256) == 64


def test_empty_directory_changes_the_candidate_tree_hash(tmp_path):
    staged = _stage_package(_make_package(tmp_path), tmp_path)
    without_directory = staged.freeze(tmp_path / "without-directory")
    (staged.workspace / "empty-directory").mkdir()
    with_directory = staged.freeze(tmp_path / "with-directory")

    assert without_directory.files == with_directory.files
    assert without_directory.directories == ()
    assert [item.path for item in with_directory.directories] == ["empty-directory"]
    assert with_directory.directories[0].mode == stat.S_IMODE(
        (staged.workspace / "empty-directory").stat().st_mode
    )
    assert without_directory.tree_sha256 != with_directory.tree_sha256


