@pytest.mark.parametrize("operation", ["modify", "create", "delete"])
def test_forbidden_modified_created_and_deleted_paths_fail(tmp_path, operation):
    root = _make_package(
        tmp_path,
        workspace_files={"locked.txt": "locked\n", "value.txt": "old\n"},
    )
    staged = _stage_package(root, tmp_path)
    (staged.workspace / "value.txt").write_text("new\n", encoding="utf-8")
    if operation == "modify":
        (staged.workspace / "locked.txt").write_text("changed\n", encoding="utf-8")
        forbidden = "locked.txt"
    elif operation == "create":
        (staged.workspace / "extra.txt").write_text("new file\n", encoding="utf-8")
        forbidden = "extra.txt"
    else:
        (staged.workspace / "locked.txt").unlink()
        forbidden = "locked.txt"

    _candidate, report = _freeze_and_grade(staged, tmp_path)

    assert all(check.passed for check in report.checks)
    assert report.status == "failed"
    assert report.forbidden_modifications == (forbidden,)


