@pytest.mark.parametrize("forgery", ["contents", "hash"])
def test_forged_candidate_snapshot_returns_a_grade_error(tmp_path, forgery):
    staged = _stage_package(EVAL_ROOT / "localized-constant", tmp_path)
    candidate = staged.freeze(tmp_path / "frozen")
    if forgery == "contents":
        path, content = candidate._contents[0]
        forged = replace(
            candidate,
            _contents=((path, bytes([content[0] ^ 1]) + content[1:]),),
        )
    else:
        forged = replace(candidate, tree_sha256="f" * 64)

    report = StaticHeldOutGrader().grade(staged, forged)

    assert report.status == "error"
    assert report.checks == ()
    assert "candidate snapshot" in report.error


def test_held_out_checks_changed_after_package_load_return_a_grade_error(tmp_path):
    root = _make_package(tmp_path)
    package = TaskPackage.load(root)
    staged = package.stage(tmp_path / "candidate")
    candidate = staged.freeze(tmp_path / "frozen")
    checks_path = root / "held_out_tests" / "checks.json"
    original = checks_path.read_bytes()
    replacement = original.replace(b"new\\n", b"old\\n")
    assert replacement != original
    assert len(replacement) == len(original)
    checks_path.write_bytes(replacement)

    report = StaticHeldOutGrader().grade(staged, candidate)

    assert report.status == "error"
    assert report.checks == ()
    assert report.error == "held-out checks changed after package validation"


def test_static_grading_never_executes_or_launches_candidate_content(
    tmp_path, monkeypatch
):
    staged = _stage_package(EVAL_ROOT / "localized-constant", tmp_path)
    answer = staged.workspace / "answer.py"
    answer.write_text(
        "ANSWER = 42\n"
        "DANGEROUS = 'tiny-llm-destructive-sentinel --delete-everything'\n"
        "raise RuntimeError('candidate modules must never be imported')\n",
        encoding="utf-8",
    )
    candidate = staged.freeze(tmp_path / "frozen")
    calls = []

    def forbidden(name):
        def fail(*args, **kwargs):
            calls.append((name, args, kwargs))
            raise AssertionError(f"static grading called {name}")

        return fail

    original_import = builtins.__import__

    def watched_import(name, *args, **kwargs):
        if name in {"answer", "config", "parser"}:
            return forbidden("candidate import")(name, *args, **kwargs)
        return original_import(name, *args, **kwargs)

    with monkeypatch.context() as guard:
        guard.setattr(subprocess, "Popen", forbidden("subprocess.Popen"))
        guard.setattr(subprocess, "run", forbidden("subprocess.run"))
        guard.setattr(os, "system", forbidden("os.system"))
        guard.setattr(builtins, "eval", forbidden("eval"))
        guard.setattr(builtins, "exec", forbidden("exec"))
        guard.setattr(builtins, "__import__", watched_import)
        report = StaticHeldOutGrader().grade(staged, candidate)

    assert report.status == "passed"
    assert calls == []


