    (root / "held_out_tests" / "checks.json").write_text(
        '{"schema_version":1,"checks":[{'
        '"type":"json_value","name":"distinct-overflow-values",'
        '"path":"value.json","pointer":"/number","expected":1e999}]}\n',
        encoding="utf-8",
    )
    staged = _stage_package(root, tmp_path)
    _candidate, report = _freeze_and_grade(staged, tmp_path)

    assert report.status == "error"
    assert "non-finite" in report.error


