def test_evaluate_task_never_exposes_run_command(tmp_path, monkeypatch):
    staged = _stage_package(EVAL_ROOT / "localized-constant", tmp_path)
    process_calls = []

    def unexpected_process(*args, **kwargs):
        process_calls.append((args, kwargs))
        raise AssertionError("a command-disabled evaluation started a process")

    monkeypatch.setattr(subprocess, "Popen", unexpected_process)
    monkeypatch.setattr(subprocess, "run", unexpected_process)
    result = evaluate_task(
        staged,
        responses(
            '{"tool":"run_command",'
            '"argv":["tiny-llm-destructive-sentinel","--delete-everything"]}',
            '{"final":"the unavailable command was rejected"}',
        ),
    )

    assert result.agent_run.events[0].action is None
    assert "not enabled" in result.agent_run.events[0].result
    assert result.metrics.malformed_actions == 1
    assert result.metrics.tool_calls == 0
    assert process_calls == []


def test_explicit_confirmation_allows_a_scripted_edit_to_pass(tmp_path):
    staged = _stage_package(EVAL_ROOT / "localized-constant", tmp_path)
    confirmations = []

    result = evaluate_task(
        staged,
        responses(
            '{"tool":"read_file","path":"answer.py"}',
            '{"tool":"edit_file","path":"answer.py",'
            '"old":"ANSWER = 41","new":"ANSWER = 42"}',
            '{"final":"corrected the constant"}',
        ),
        confirm_tool=lambda action: confirmations.append(action.tool) or True,
    )

    assert confirmations == ["edit_file"]
    assert "ANSWER = 42" in (staged.workspace / "answer.py").read_text(encoding="utf-8")
    assert result.agent_run.completed
    assert result.grade.status == "passed"
    assert result.task_success is True
    assert result.agent_run.task_success is True


