def test_metrics_use_durable_compactions_and_fail_closed_on_partial_stats(tmp_path):
    workspace = tmp_path / "metrics-workspace"
    workspace.mkdir()
    store = SessionStore(workspace, "metrics-model")
    session = store.create()
    session.append(
        "assistant_message",
        content="measured turn",
        generation={
            "input_tokens": 11,
            "output_tokens": 2,
            "reused_tokens": 3,
            "rewound_tokens": 1,
            "prefilled_tokens": 8,
            "latency_seconds": 0.25,
        },
        context={"visible_tool_result_bytes": 7},
    )
    session.append("compaction", summary="bounded inert summary")
    session.append("assistant_message", content="turn without generation stats")
    reloaded = store.load(session.session_id)
    agent_run = AgentRun(
        True,
        "completed",
        "done",
        (),
        (),
        session_id=session.session_id,
    )

    metrics = aggregate_metrics(reloaded, agent_run, 1.5)

    assert metrics.model_turns == 2
    assert metrics.compactions == 1
    assert metrics.input_tokens is None
    assert metrics.output_tokens is None
    assert metrics.reused_tokens is None
    assert metrics.rewound_tokens is None
    assert metrics.prefilled_tokens is None
    assert metrics.generation_latency_seconds is None
    assert metrics.visible_tool_result_bytes is None


