def test_evaluation_and_session_reuse_are_rejected_before_mutation(tmp_path):
    staged = _stage_package(EVAL_ROOT / "localized-constant", tmp_path)
    store = SessionStore(staged.workspace, "evaluation")
    session = store.create()
    evaluate_task(
        staged,
        responses('{"final":"first evaluation"}'),
        session=session,
    )
    answer = staged.workspace / "answer.py"
    before = answer.read_bytes()
    model_calls = []
    confirmation_calls = []

    def unexpected_generate(_messages):
        model_calls.append(True)
        return '{"tool":"write_file","path":"answer.py","content":"ANSWER = 42\\n"}'

    def confirm(action):
        confirmation_calls.append(action)
        return True

    with pytest.raises(ValueError, match="already has a frozen candidate"):
        evaluate_task(
            staged,
            unexpected_generate,
            session=session,
            confirm_tool=confirm,
        )

    alternate = replace(staged, destination=tmp_path / "alternate-stage")
    with pytest.raises(ValueError, match="sessions are single-use"):
        evaluate_task(
            alternate,
            unexpected_generate,
            session=session,
            confirm_tool=confirm,
        )

    assert answer.read_bytes() == before
    assert not alternate.destination.exists()
    assert model_calls == []
    assert confirmation_calls == []


def test_evaluation_rejects_rebound_workspace_before_session_or_model(tmp_path):
    staged = _stage_package(EVAL_ROOT / "localized-constant", tmp_path)
    moved = staged.destination / "original-workspace"
    staged.workspace.rename(moved)
    staged.workspace.mkdir()
    replacement = staged.workspace / "replacement.txt"
    replacement.write_text("must remain untouched\n", encoding="utf-8")
    model_calls = []

    with pytest.raises(ValueError, match="identity changed"):
        evaluate_task(
            staged,
            lambda messages: model_calls.append(messages) or '{"final":"unsafe"}',
        )

    assert model_calls == []
    assert replacement.read_text(encoding="utf-8") == "must remain untouched\n"
    assert not (staged.workspace / ".tiny-llm").exists()


def test_evaluation_events_precede_hidden_grading_and_preserve_unknown_metrics(
    tmp_path, monkeypatch
):
    staged = _stage_package(EVAL_ROOT / "localized-constant", tmp_path)
    store = SessionStore(staged.workspace, "evaluation")
    session = store.create()
    observed_grade_events = []
    original_grade = StaticHeldOutGrader.grade

    def observed_grade(grader, staged_task, candidate):
        observed_grade_events.append(tuple(event.type for event in session.events))
        assert session.events[-1].type == "evaluation_started"
        return original_grade(grader, staged_task, candidate)

    monkeypatch.setattr(StaticHeldOutGrader, "grade", observed_grade)
    ticks = iter((10.0, 12.5))
    result = evaluate_task(
        staged,
        responses('{"final":"finished without changing files"}'),
        session=session,
        clock=lambda: next(ticks),
    )
    reloaded = store.load(session.session_id)
    event_types = [event.type for event in reloaded.events]
    started_index = event_types.index("evaluation_started")
    result_index = event_types.index("evaluation_result")
    pre_grade_trace = json.dumps(
        [event.to_dict() for event in reloaded.events[: started_index + 1]],
        sort_keys=True,
    )

    assert observed_grade_events
    assert started_index < result_index
    assert event_types[-2:] == ["evaluation_started", "evaluation_result"]
    assert '"expected"' not in pre_grade_trace
    assert result.metrics.model_turns == 1
    assert result.metrics.tool_calls == 0
    assert result.metrics.malformed_actions == 0
    assert result.metrics.tool_errors == 0
    assert result.metrics.input_tokens is None
    assert result.metrics.output_tokens is None
    assert result.metrics.reused_tokens is None
    assert result.metrics.rewound_tokens is None
    assert result.metrics.prefilled_tokens is None
    assert result.metrics.visible_tool_result_bytes is None
    assert result.metrics.generation_latency_seconds is None
    assert result.metrics.compactions == 0
    assert result.metrics.wall_time_seconds == 2.5
    assert result.metrics.terminal_reason == "completed"
    assert aggregate_metrics(reloaded, result.agent_run, 2.5) == result.metrics
